import { SyntheticMultiProtocolMonitorConstraintDto } from './synthetic-multi-protocol-monitor-constraint-dto';
import { SyntheticMultiProtocolMonitorStepDtoProperties } from './synthetic-multi-protocol-monitor-step-dto-properties';
import { SyntheticMultiProtocolMonitorStepDtoRequestType } from './synthetic-multi-protocol-monitor-step-dto-request-type';
import { SyntheticMultiProtocolRequestConfigurationDto } from './synthetic-multi-protocol-request-configuration-dto';
/**
 * The step of a network availability monitor.
 */
export interface SyntheticMultiProtocolMonitorStepDto {
    /**
     * The list of constraints which apply to all requests in the step.
     */
    constraints: SyntheticMultiProtocolMonitorConstraintDto[];
    /**
     * Step name.
     */
    name: string;
    properties: SyntheticMultiProtocolMonitorStepDtoProperties;
    /**
     * Request configurations.
     */
    requestConfigurations: SyntheticMultiProtocolRequestConfigurationDto[];
    requestType: SyntheticMultiProtocolMonitorStepDtoRequestType;
    /**
     * Target filter.
     */
    targetFilter?: string;
    /**
     * Target list.
     */
    targetList: string[];
}
